import numpy as np
import pandas as pd

meta_full = meta.copy()

# Get dropped samples
dropped = meta_full[~meta_full['pipeline_in_counts']]
retained = meta_full[meta_full['pipeline_in_counts']]

# Check all columns for dropped
dropped_info = {}
for col in dropped.columns:
    non_null = dropped[col].notna().sum()
    if non_null > 0:
        if dropped[col].dtype in ['float64', 'int64', 'float32', 'int32', 'Int64', 'Float64']:
            vals = dropped[col].dropna()
            dropped_info[col] = {'n_nonnull': non_null, 'min': float(vals.min()), 'max': float(vals.max()), 'median': float(vals.median())}
        else:
            vals = dropped[col].dropna()
            dropped_info[col] = {'n_nonnull': non_null, 'unique': vals.unique().tolist()[:10]}

result = {'dropped_info': dropped_info, 'dropped_n': len(dropped), 'retained_n': len(retained)}
